// SLSA-style provenance statement (in-toto Statement v1, predicate https://slsa.dev/provenance/v1) for one image,
// generated by this repository's own workflow. It is signed by the release key like the image, but it is NOT a
// SLSA Build L3 claim: the build runs in the same job that holds the signing credentials, with no isolated builder.
export function provenance({
  imageName,
  digest,
  repo,
  sha,
  ref,
  workflow,
  runId,
  runAttempt,
  serverUrl,
  builtAt,
  releaseNumber,
  lockfileSha256,
}) {
  return {
    _type: 'https://in-toto.io/Statement/v1',
    subject: [{ name: imageName, digest: { sha256: digest.replace(/^sha256:/, '') } }],
    predicateType: 'https://slsa.dev/provenance/v1',
    predicate: {
      buildDefinition: {
        buildType:
          'https://github.com/zainnaeem28/enterprise-app/docs/DEVOPS-PLAN.md#6.1/release-build/v1',
        externalParameters: {
          workflow: `${repo}/.github/workflows/${workflow}@${ref}`,
          ref,
          release_number: releaseNumber,
        },
        internalParameters: { github_event: 'push' },
        resolvedDependencies: [
          { uri: `git+${serverUrl}/${repo}@${ref}`, digest: { gitCommit: sha } },
          { uri: 'pnpm-lock.yaml', digest: { sha256: lockfileSha256 } },
        ],
      },
      runDetails: {
        builder: { id: `${serverUrl}/${repo}/.github/workflows/${workflow}@${ref}` },
        metadata: {
          invocationId: `${serverUrl}/${repo}/actions/runs/${runId}/attempts/${runAttempt}`,
          finishedOn: builtAt,
        },
      },
    },
  };
}
